solution.main.cpp:
#include <iostream>

int main()
{
    int a{ 5 };
    int b{ 9 };

    int temp{ a };
    a = b;
    b = temp;

    std::cout << "a = " << a << '\n';
    std::cout << "b = " << b << '\n';
    return 0;
}
